#!/bin/sh
# Builds the GSI1 programs of the SU testbench (sim/tb/su/*.s) into
# $readmemh images, one 32-bit word per line (NAME.hex), and runs the
# reference model (tools/gsi1model.py) for the expected registers
# (NAME.exp).  rand.s is generated by gen_rand.py first.  The images are
# committed, so sim/run.sh needs no Python; run this after changing a
# program.  Lanes per program: the "lanes" table below.
#   tools/su-tests.sh
# Copyright (C) 2026 Awe Morris; SPDX-License-Identifier: Zlib
set -eu
root=$(cd "$(dirname -- "$0")/.." && pwd)
src=$root/sim/tb/su
export PYTHONDONTWRITEBYTECODE=1
timeout 60 python3 -I "$src/gen_rand.py" "$src/rand.s"
for p in alu:128 branch:100 rand:128; do
	n=${p%%:*}
	lanes=${p#*:}
	timeout 60 python3 -I "$root/tools/gsi1asm.py" "$src/$n.s" -o "$src/$n.hex"
	timeout 60 python3 -I "$root/tools/gsi1model.py" "$src/$n.s" --lanes "$lanes" \
		-o "$src/$n.exp"
done
